    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
import math
# choose parameters
while True:
    n = rng.randint(8, 12)  # ensure enough elements for nontrivial combinatorics
    k = rng.randint(3, min(6, n-1))  # 3 <= k <= 6, and k < n
    r = rng.randint(2, min(4, k-1))  # 2 <= r < k, with r not too large; avoids trivial r=k
    # generate distinct values with spread
    pool_max = rng.randint(180, 400)
    values = rng.sample(range(2, pool_max + 1), n)
    arr = sorted(values)
    # avoid arithmetic progression (too regular)
    diffs = [arr[i+1] - arr[i] for i in range(n-1)]
    if all(d == diffs[0] for d in diffs):
        continue
    # compute weights for difficulty screening
    def comb(a, b):
        if b < 0 or b > a:
            return 0
        return math.comb(a, b)
    Ws = []
    for j in range(1, n+1):
        limit = min(r-1, n-j, k-1)
        w = 0
        for t in range(0, limit+1):
            if k-1-t <= j-1:
                w += comb(n-j, t) * comb(j-1, k-1-t)
        Ws.append(w)
    # require nontrivial distribution of weights
    if len(set(Ws)) < 3:
        continue
    # shuffle presentation order to prevent easy sorting by sight
    rng.shuffle(values)
    set_elements = ", ".join(str(x) for x in values)
    return {
        'n': n,
        'k': k,
        'r': r,
        'values': values,
        'set_elements': set_elements
    }

